-- Run once in your Peppermoon Supabase project: SQL Editor → New query → Run.
-- Creates guide storage and imports the current 17 guides. Existing edits are preserved.
begin;
create table if not exists public.pepper_guides (
 id uuid primary key default gen_random_uuid(),
 slug text not null unique check (length(slug)<=100 and slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
 title text not null check (length(trim(title)) between 1 and 180),
 franchise text not null check (length(trim(franchise)) between 1 and 160),
 collection text not null check (collection in ('screen','games')),
 summary text not null default '' check (length(summary)<=600),
 intro text not null default '' check (length(intro)<=30000),
 notes text not null default '' check (length(notes)<=50000),
 image_url text not null default '',
 image_alt text not null default '' check (length(image_alt)<=250),
 display_order integer not null default 0 check (display_order between 0 and 9999),
 status text not null default 'draft' check (status in ('draft','published')),
 release_sections jsonb not null default '[]'::jsonb check (jsonb_typeof(release_sections)='array'),
 story_sections jsonb not null default '[]'::jsonb check (jsonb_typeof(story_sections)='array'),
 created_by uuid references auth.users(id) default auth.uid(),
 published_at timestamptz,
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now(),
 constraint pepper_guides_published_content check (status<>'published' or (length(trim(summary))>0 and jsonb_array_length(release_sections)>0))
);
create index if not exists pepper_guides_public_order on public.pepper_guides (status,display_order,franchise);
create or replace function public.pepper_guides_touch_updated_at() returns trigger language plpgsql set search_path=public as $$
begin new.updated_at=now(); return new; end;
$$;
drop trigger if exists pepper_guides_updated_at on public.pepper_guides;
create trigger pepper_guides_updated_at before update on public.pepper_guides for each row execute function public.pepper_guides_touch_updated_at();
alter table public.pepper_guides enable row level security;
revoke all on public.pepper_guides from anon,authenticated;
grant select on public.pepper_guides to anon,authenticated;
grant insert,update on public.pepper_guides to authenticated;
drop policy if exists pepper_guides_public_read on public.pepper_guides;
create policy pepper_guides_public_read on public.pepper_guides for select to anon,authenticated using (status='published');
drop policy if exists pepper_guides_admin on public.pepper_guides;
create policy pepper_guides_admin on public.pepper_guides for all to authenticated
 using (exists(select 1 from public.profiles where id=auth.uid() and role='admin'))
 with check (exists(select 1 from public.profiles where id=auth.uid() and role='admin'));
-- The existing article-images bucket is used for guide cover uploads under admin permissions.
insert into public.pepper_guides (slug,title,franchise,collection,summary,intro,notes,image_url,image_alt,status,display_order,release_sections,story_sections,published_at)
select slug,title,franchise,collection,summary,intro,notes,image_url,image_alt,status,display_order,release_sections,story_sections,now()
from jsonb_to_recordset($peppermoon_guides_seed$[{"slug": "star-wars", "title": "Star Wars Watch Order", "franchise": "Star Wars", "collection": "screen", "summary": "Follow the main canon story across the prequel, original and sequel eras, including animated and live-action series.", "intro": "Star Wars gives you two very different ways into its galaxy. Start with the original films and you discover its mysteries alongside Luke Skywalker. Start earlier in the timeline and you watch the Republic’s decline before the rebellion begins. Both approaches work, but they reveal information in different ways.\n\nThis guide covers the main canon films and narrative series, including animation. Short-form collections and non-canon productions are explained separately below.", "notes": "## Where do the anthology shows fit?\n\nTales of the Jedi, Tales of the Empire and Tales of the Underworld move between periods. They cannot honestly occupy one fixed position on a timeline. Watch Tales of the Jedi after the prequel trilogy and The Clone Wars; save the other Tales collections until you know the related characters from the main shows. Forces of Destiny (2017) also consists of short adventures spread across eras.\n\nThe Clone Wars itself was not originally broadcast in strict story order. For a detailed rewatch, use Lucasfilm’s official episode chronology. For a first watch, its normal episode order remains approachable.\n\nVisions, LEGO productions and older Legends material such as the 2003 Clone Wars series are optional viewing outside this main canon route. They should not be inserted as if every production shares one history.\n\n## Peppermoon’s recommendation\n\nStart with Episodes IV, V and VI, then I, II and III, followed by VII, VIII and IX. Add Rogue One and Andor for the rebellion, or The Mandalorian for a new adventure. You do not need to finish every animated series before enjoying your first Star Wars film.\n\nSources: Lucasfilm viewing guide (https://www.starwars.com/news/star-wars-movies-and-series-guide); Young Jedi Adventures setting (https://www.lucasfilm.com/productions/star-wars-young-jedi-adventures/).", "image_url": "", "image_alt": "", "status": "published", "display_order": 1, "release_sections": [{"heading": "Release order", "note": "", "items": [{"rank": 1, "title": "Episode IV — A New Hope", "year": "1977", "type": "movie", "notes": ""}, {"rank": 2, "title": "Episode V — The Empire Strikes Back", "year": "1980", "type": "movie", "notes": ""}, {"rank": 3, "title": "Episode VI — Return of the Jedi", "year": "1983", "type": "movie", "notes": ""}, {"rank": 4, "title": "Episode I — The Phantom Menace", "year": "1999", "type": "movie", "notes": ""}, {"rank": 5, "title": "Episode II — Attack of the Clones", "year": "2002", "type": "movie", "notes": ""}, {"rank": 6, "title": "Episode III — Revenge of the Sith", "year": "2005", "type": "movie", "notes": ""}, {"rank": 7, "title": "The Clone Wars — animated film", "year": "2008", "type": "movie", "notes": "Animated Film"}, {"rank": 8, "title": "The Clone Wars — animated series", "year": "2008", "type": "tv", "notes": "Animated TV series"}, {"rank": 9, "title": "Rebels", "year": "2014", "type": "tv", "notes": ""}, {"rank": 10, "title": "Episode VII — The Force Awakens", "year": "2015", "type": "movie", "notes": ""}, {"rank": 11, "title": "Rogue One: A Star Wars Story", "year": "2016", "type": "movie", "notes": ""}, {"rank": 12, "title": "Episode VIII — The Last Jedi", "year": "2017", "type": "movie", "notes": ""}, {"rank": 13, "title": "Solo: A Star Wars Story", "year": "2018", "type": "movie", "notes": ""}, {"rank": 14, "title": "Resistance", "year": "2018", "type": "tv", "notes": ""}, {"rank": 15, "title": "The Mandalorian", "year": "2019", "type": "tv", "notes": ""}, {"rank": 16, "title": "Episode IX — The Rise of Skywalker", "year": "2019", "type": "movie", "notes": ""}, {"rank": 17, "title": "The Bad Batch", "year": "2021", "type": "tv", "notes": ""}, {"rank": 18, "title": "The Book of Boba Fett", "year": "2021", "type": "tv", "notes": ""}, {"rank": 19, "title": "Obi-Wan Kenobi", "year": "2022", "type": "tv", "notes": ""}, {"rank": 20, "title": "Andor", "year": "2022", "type": "tv", "notes": ""}, {"rank": 21, "title": "Tales of the Jedi", "year": "2022", "type": "tv", "notes": ""}, {"rank": 22, "title": "Young Jedi Adventures", "year": "2023", "type": "tv", "notes": ""}, {"rank": 23, "title": "Ahsoka", "year": "2023", "type": "tv", "notes": ""}, {"rank": 24, "title": "Tales of the Empire", "year": "2024", "type": "tv", "notes": ""}, {"rank": 25, "title": "The Acolyte", "year": "2024", "type": "tv", "notes": ""}, {"rank": 26, "title": "Skeleton Crew", "year": "2024", "type": "tv", "notes": ""}, {"rank": 27, "title": "Tales of the Underworld", "year": "2025", "type": "tv", "notes": ""}, {"rank": 28, "title": "Maul – Shadow Lord", "year": "2026", "type": "tv", "notes": ""}, {"rank": 29, "title": "The Mandalorian and Grogu", "year": "2026", "type": "movie", "notes": ""}]}], "story_sections": [{"heading": "Story order: a practical route through the eras", "note": "", "items": [{"rank": 1, "title": "Young Jedi Adventures", "year": "2023", "type": "tv", "notes": "the High Republic, long before the Skywalker films"}, {"rank": 2, "title": "The Acolyte", "year": "2024", "type": "tv", "notes": "a later period of the High Republic"}, {"rank": 3, "title": "The Phantom Menace", "year": "1999", "type": "movie", "notes": ""}, {"rank": 4, "title": "Attack of the Clones", "year": "2002", "type": "movie", "notes": ""}, {"rank": 5, "title": "The Clone Wars — animated film", "year": "2008", "type": "movie", "notes": "The film introduces the Clone Wars and the series continues the conflict; the series’ final arc overlaps Revenge of the Sith."}, {"rank": 5, "title": "The Clone Wars — animated series", "year": "2008", "type": "tv", "notes": "The film introduces the Clone Wars and the series continues the conflict; the series’ final arc overlaps Revenge of the Sith."}, {"rank": 6, "title": "Revenge of the Sith", "year": "2005", "type": "movie", "notes": ""}, {"rank": 7, "title": "The Bad Batch", "year": "2021", "type": "tv", "notes": "begins during the Republic’s fall and follows the new Empire"}, {"rank": 8, "title": "Maul – Shadow Lord", "year": "2026", "type": "tv", "notes": "the early Imperial period"}, {"rank": 9, "title": "Solo", "year": "2018", "type": "movie", "notes": ""}, {"rank": 10, "title": "Obi-Wan Kenobi", "year": "2022", "type": "tv", "notes": ""}, {"rank": 11, "title": "Andor", "year": "2022", "type": "tv", "notes": "These are two separate series whose rebellion-era stories overlap. Watch each series in its own episode order; Andor leads directly into Rogue One."}, {"rank": 11, "title": "Star Wars Rebels", "year": "2014", "type": "tv", "notes": "These are two separate series whose rebellion-era stories overlap. Watch each series in its own episode order; Andor leads directly into Rogue One."}, {"rank": 12, "title": "Rogue One", "year": "2016", "type": "movie", "notes": ""}, {"rank": 13, "title": "A New Hope", "year": "1977", "type": "movie", "notes": ""}, {"rank": 14, "title": "The Empire Strikes Back", "year": "1980", "type": "movie", "notes": ""}, {"rank": 15, "title": "Return of the Jedi", "year": "1983", "type": "movie", "notes": ""}, {"rank": 16, "title": "The Mandalorian, seasons 1–2", "year": "2019", "type": "tv", "notes": ""}, {"rank": 17, "title": "The Book of Boba Fett", "year": "2021", "type": "tv", "notes": "its present-day storyline belongs here; it also contains earlier flashbacks"}, {"rank": 18, "title": "The Mandalorian, season 3", "year": "2019", "type": "tv", "notes": ""}, {"rank": 19, "title": "Ahsoka", "year": "2023", "type": "tv", "notes": "These are separate series set in the New Republic era. Their timelines are close, but this is an era grouping rather than a scene-by-scene crossover order."}, {"rank": 19, "title": "Skeleton Crew", "year": "2024", "type": "tv", "notes": "These are separate series set in the New Republic era. Their timelines are close, but this is an era grouping rather than a scene-by-scene crossover order."}, {"rank": 20, "title": "The Mandalorian and Grogu", "year": "2026", "type": "movie", "notes": "follows the Mandalorian television story"}, {"rank": 21, "title": "Star Wars Resistance — Season 1", "year": "2018", "type": "tv", "notes": "Their closing events overlap."}, {"rank": 21, "title": "Star Wars: The Force Awakens", "year": "2015", "type": "movie", "notes": "Their closing events overlap."}, {"rank": 22, "title": "Star Wars: The Last Jedi", "year": "2017", "type": "movie", "notes": "The series continues through the sequel era, with events overlapping the film timeline."}, {"rank": 22, "title": "Star Wars Resistance — Season 2", "year": "2018", "type": "tv", "notes": "The series continues through the sequel era, with events overlapping the film timeline."}, {"rank": 23, "title": "The Rise of Skywalker", "year": "2019", "type": "movie", "notes": ""}]}]}, {"slug": "star-trek", "title": "Star Trek Watch Order", "franchise": "Star Trek", "collection": "screen", "summary": "Explore the Prime timeline, classic crews and the separate Kelvin film universe.", "intro": "Star Trek is less a single marathon than a collection of crews exploring the same enormous future. Its shows often run alongside one another, and some jump centuries forward. The easiest approach is to choose a crew, follow its adventures, and then expand your journey.\n\nThese lists cover the main television series and feature films. Series are listed by premiere year; short-form spin-offs are treated as extras.", "notes": "## Peppermoon’s recommendation\n\nFor a modern introduction, start with Strange New Worlds. For the classic experience, start with The Original Series or The Next Generation. Save crossover-heavy Picard and the reference-rich Lower Decks until you have some familiarity with the earlier crews.\n\nSources: Star Trek official viewing guide (https://www.startrek.com/gallery/how-to-watch-every-star-trek-series-and-movie-in-the-right-order); Popverse’s franchise timeline (https://www.thepopverse.com/tv-movies-star-trek-in-order-paramount-plus-movie-movies-strange-new-worlds-discovery-picard-next-generation); Section 31 setting (https://en.wikipedia.org/wiki/Star_Trek:_Section_31).", "image_url": "", "image_alt": "", "status": "published", "display_order": 2, "release_sections": [{"heading": "Release order", "note": "", "items": [{"rank": 1, "title": "The Original Series", "year": "1966", "type": "tv", "notes": ""}, {"rank": 2, "title": "The Animated Series", "year": "1973", "type": "tv", "notes": "Animated TV series"}, {"rank": 3, "title": "The Motion Picture", "year": "1979", "type": "movie", "notes": ""}, {"rank": 4, "title": "II: The Wrath of Khan", "year": "1982", "type": "movie", "notes": ""}, {"rank": 5, "title": "III: The Search for Spock", "year": "1984", "type": "movie", "notes": ""}, {"rank": 6, "title": "IV: The Voyage Home", "year": "1986", "type": "movie", "notes": ""}, {"rank": 7, "title": "The Next Generation", "year": "1987", "type": "tv", "notes": ""}, {"rank": 8, "title": "V: The Final Frontier", "year": "1989", "type": "movie", "notes": ""}, {"rank": 9, "title": "VI: The Undiscovered Country", "year": "1991", "type": "movie", "notes": ""}, {"rank": 10, "title": "Deep Space Nine", "year": "1993", "type": "tv", "notes": ""}, {"rank": 11, "title": "Generations", "year": "1994", "type": "movie", "notes": ""}, {"rank": 12, "title": "Voyager", "year": "1995", "type": "tv", "notes": ""}, {"rank": 13, "title": "First Contact", "year": "1996", "type": "movie", "notes": ""}, {"rank": 14, "title": "Insurrection", "year": "1998", "type": "movie", "notes": ""}, {"rank": 15, "title": "Enterprise", "year": "2001", "type": "tv", "notes": ""}, {"rank": 16, "title": "Nemesis", "year": "2002", "type": "movie", "notes": ""}, {"rank": 17, "title": "Star Trek", "year": "2009", "type": "movie", "notes": ""}, {"rank": 18, "title": "Into Darkness", "year": "2013", "type": "movie", "notes": ""}, {"rank": 19, "title": "Beyond", "year": "2016", "type": "movie", "notes": ""}, {"rank": 20, "title": "Discovery", "year": "2017", "type": "tv", "notes": ""}, {"rank": 21, "title": "Short Treks", "year": "2018", "type": "tv", "notes": ""}, {"rank": 22, "title": "Picard", "year": "2020", "type": "tv", "notes": ""}, {"rank": 23, "title": "Lower Decks", "year": "2020", "type": "tv", "notes": ""}, {"rank": 24, "title": "Prodigy", "year": "2021", "type": "tv", "notes": ""}, {"rank": 25, "title": "Strange New Worlds", "year": "2022", "type": "tv", "notes": ""}, {"rank": 26, "title": "Section 31 — film", "year": "2025", "type": "movie", "notes": ""}, {"rank": 27, "title": "Starfleet Academy", "year": "2026", "type": "tv", "notes": ""}]}], "story_sections": [{"heading": "Story order: the Prime timeline", "note": "\n\nThis is an era-based route, not a claim that all of Deep Space Nine happens before Voyager. You can watch those shows separately without constantly switching episodes. Short Treks spans different periods; use it as companion viewing after meeting the relevant crews.", "items": [{"rank": 1, "title": "Enterprise", "year": "2001", "type": "tv", "notes": "the 22nd century, before the familiar Federation era"}, {"rank": 2, "title": "Discovery, seasons 1–2", "year": "2017", "type": "tv", "notes": "the 23rd century before Kirk’s main adventures"}, {"rank": 3, "title": "Strange New Worlds", "year": "2022", "type": "tv", "notes": "Captain Pike’s Enterprise"}, {"rank": 4, "title": "The Original Series", "year": "1966", "type": "tv", "notes": ""}, {"rank": 5, "title": "The Animated Series", "year": "1973", "type": "tv", "notes": ""}, {"rank": 6, "title": "The Motion Picture", "year": "1979", "type": "movie", "notes": ""}, {"rank": 7, "title": "The Wrath of Khan", "year": "1982", "type": "movie", "notes": ""}, {"rank": 8, "title": "The Search for Spock", "year": "1984", "type": "movie", "notes": ""}, {"rank": 9, "title": "The Voyage Home", "year": "1986", "type": "movie", "notes": ""}, {"rank": 10, "title": "The Final Frontier", "year": "1989", "type": "movie", "notes": ""}, {"rank": 11, "title": "The Undiscovered Country", "year": "1991", "type": "movie", "notes": ""}, {"rank": 12, "title": "Section 31", "year": "2025", "type": "movie", "notes": "the early 24th century. Its protagonist’s personal journey also depends on Discovery, including season 3"}, {"rank": 13, "title": "The Next Generation", "year": "1987", "type": "tv", "notes": "begins in 2364"}, {"rank": 14, "title": "Deep Space Nine", "year": "1993", "type": "tv", "notes": "begins in 2369, overlapping The Next Generation’s final seasons"}, {"rank": 15, "title": "Generations", "year": "1994", "type": "movie", "notes": "its main story follows The Next Generation finale"}, {"rank": 16, "title": "Voyager", "year": "1995", "type": "tv", "notes": "begins in 2371, overlapping Deep Space Nine"}, {"rank": 17, "title": "First Contact", "year": "1996", "type": "movie", "notes": ", then Insurrection — during the wider Deep Space Nine/Voyager period Film; 1998 • Film"}, {"rank": 18, "title": "Nemesis", "year": "2002", "type": "movie", "notes": "after Voyager’s main television story"}, {"rank": 19, "title": "Lower Decks", "year": "2020", "type": "tv", "notes": ""}, {"rank": 20, "title": "Prodigy", "year": "2021", "type": "tv", "notes": ""}, {"rank": 21, "title": "Picard", "year": "2020", "type": "tv", "notes": ""}, {"rank": 22, "title": "Discovery, seasons 3–5", "year": "2017", "type": "tv", "notes": "the 32nd century, with an epilogue later still"}, {"rank": 23, "title": "Starfleet Academy", "year": "2026", "type": "tv", "notes": "the 32nd-century setting following Discovery’s main late-era story, not necessarily after its distant epilogue"}]}, {"heading": "Story order: the Kelvin timeline, a separate three-film route", "note": "\n\nWatch Star Trek (2009) → Into Darkness (2013) → Beyond (2016). Their main adventures take place in an alternate 23rd century. They do not replace the events of The Original Series in the Prime timeline.", "items": []}]}, {"slug": "predator", "title": "Predator Watch Order", "franchise": "Predator", "collection": "screen", "summary": "Track the hunts from Prey’s historical setting to the distant future of Badlands.", "intro": "The Predator franchise keeps changing the hunting ground. Jungles, cities, historical battlefields and distant worlds all become tests of survival. Because many entries introduce new human characters, you have more freedom here than in a tightly connected superhero saga.", "notes": "## Do the Alien crossovers matter?\n\nThey are optional detours. Watch the two crossover films together if you want the creatures facing each other, but do not use them to force every Alien and Predator production into a perfectly consistent shared chronology.\n\n## Peppermoon’s recommendation\n\nStart with Predator, then try Prey. That pairing shows how the same survival premise works across very different settings. Continue in release order if you want to see the franchise experiment with its creature and mythology.\n\nSources: Predator viewing guide (https://www.space.com/predator-movies-in-order); Killer of Killers official page (https://www.20thcenturystudios.com/movies/predator-killer-of-killers); Badlands official setting (https://www.20thcenturystudios.com/movies/predator-badlands).", "image_url": "", "image_alt": "", "status": "published", "display_order": 3, "release_sections": [{"heading": "Release order", "note": "", "items": [{"rank": 1, "title": "Predator", "year": "1987", "type": "movie", "notes": ""}, {"rank": 2, "title": "Predator 2", "year": "1990", "type": "movie", "notes": ""}, {"rank": 3, "title": "Alien vs. Predator", "year": "2004", "type": "movie", "notes": "optional crossover — Film"}, {"rank": 4, "title": "Aliens vs. Predator: Requiem", "year": "2007", "type": "movie", "notes": "optional crossover — Film"}, {"rank": 5, "title": "Predators", "year": "2010", "type": "movie", "notes": ""}, {"rank": 6, "title": "The Predator", "year": "2018", "type": "movie", "notes": ""}, {"rank": 7, "title": "Prey", "year": "2022", "type": "movie", "notes": ""}, {"rank": 8, "title": "Predator: Killer of Killers", "year": "2025", "type": "movie", "notes": ""}, {"rank": 9, "title": "Predator: Badlands", "year": "2025", "type": "movie", "notes": ""}]}], "story_sections": [{"heading": "Story order", "note": "\n\nFor the straightforward historical-to-future route, watch:\n\nKiller of Killers (2025 • Anthology Film) needs its own note. Its historical segments travel from the Viking age to feudal Japan and World War II, while its connecting story is set later. Placing the entire film before Prey because its first segment is older would be misleading. Watch it after Predator 2, or simply keep its release-order position. That is a viewing recommendation, not a confirmed exact date for its framing story.", "items": [{"rank": 1, "title": "Prey", "year": "2022", "type": "movie", "notes": "set in 1719"}, {"rank": 2, "title": "Predator", "year": "1987", "type": "movie", "notes": "its contemporary 1980s setting"}, {"rank": 3, "title": "Predator 2", "year": "1990", "type": "movie", "notes": "set in 1997, despite its 1990 release"}, {"rank": 4, "title": "Alien vs. Predator", "year": "2004", "type": "movie", "notes": "optional, set in 2004"}, {"rank": 5, "title": "Aliens vs. Predator: Requiem", "year": "2007", "type": "movie", "notes": "optional, directly follows the previous crossover"}, {"rank": 6, "title": "Predators", "year": "2010", "type": "movie", "notes": "a modern-era story on an alien hunting preserve"}, {"rank": 7, "title": "The Predator", "year": "2018", "type": "movie", "notes": "a later modern-era hunt"}, {"rank": 8, "title": "Predator: Badlands", "year": "2025", "type": "movie", "notes": "a future setting on a distant planet"}]}]}, {"slug": "lord-of-the-rings", "title": "The Lord of the Rings Watch Order", "franchise": "The Lord of the Rings", "collection": "screen", "summary": "Travel through Middle-earth and learn where The Hobbit, Rings of Power and the films fit.", "intro": "Middle-earth can begin with Bilbo leaving his comfortable home or with Frodo inheriting a burden he never asked for. Chronology gives you the earlier adventure first. Release order introduces the world through the films that established its modern screen identity.\n\nThis guide focuses on Peter Jackson’s six films and The War of the Rohirrim, with The Rings of Power explained separately.", "notes": "## Where does The Rings of Power fit?\n\nThe Rings of Power (2022 • TV series) explores the Second Age, thousands of years before the main Hobbit and Lord of the Rings adventures. On a broad Middle-earth history chart, it comes first. However, it is a separate adaptation with its own creative choices; it should not be presented as a seamless prequel to every detail of Jackson’s films.\n\nFor an expanded thematic marathon, begin with the released seasons of The Rings of Power, then follow the film chronology above. For a consistent film marathon, keep the series separate.\n\nThe older animated adaptations — The Hobbit (1977 • Animated Film), The Lord of the Rings (1978 • Animated Film) and The Return of the King (1980 • Animated Film) — are also separate screen interpretations, not missing chapters in Jackson’s saga.\n\n## Peppermoon’s recommendation\n\nStart with Fellowship, The Two Towers and Return of the King. Then return for Bilbo’s adventure. The theatrical editions are a comfortable first viewing; the extended editions are rewarding when you want more time with the characters and world.\n\nSources: Amazon’s Middle-earth viewing guide (https://www.aboutamazon.com/news/entertainment/where-to-watch-lord-of-the-rings); Expanded screen watch order (https://www.gamesradar.com/how-to-watch-lord-of-the-rings-in-order-movies-shows/).", "image_url": "", "image_alt": "", "status": "published", "display_order": 4, "release_sections": [{"heading": "Release order", "note": "", "items": [{"rank": 1, "title": "The Lord of the Rings: The Fellowship of the Ring", "year": "2001", "type": "movie", "notes": ""}, {"rank": 2, "title": "The Lord of the Rings: The Two Towers", "year": "2002", "type": "movie", "notes": ""}, {"rank": 3, "title": "The Lord of the Rings: The Return of the King", "year": "2003", "type": "movie", "notes": ""}, {"rank": 4, "title": "The Hobbit: An Unexpected Journey", "year": "2012", "type": "movie", "notes": ""}, {"rank": 5, "title": "The Hobbit: The Desolation of Smaug", "year": "2013", "type": "movie", "notes": ""}, {"rank": 6, "title": "The Hobbit: The Battle of the Five Armies", "year": "2014", "type": "movie", "notes": ""}, {"rank": 7, "title": "The Lord of the Rings: The Rings of Power — Seasons 1–2 (2022, 2024) — TV series; separate screen continuity", "year": "", "type": "tv", "notes": ""}, {"rank": 8, "title": "The Lord of the Rings: The War of the Rohirrim", "year": "2024", "type": "movie", "notes": ""}]}], "story_sections": [{"heading": "Story order", "note": "", "items": [{"rank": 1, "title": "The War of the Rohirrim", "year": "2024", "type": "movie", "notes": "Rohan’s past, roughly 183 years before the events of the Lord of the Rings trilogy Animated Film"}, {"rank": 2, "title": "An Unexpected Journey", "year": "2012", "type": "movie", "notes": ""}, {"rank": 3, "title": "The Desolation of Smaug", "year": "2013", "type": "movie", "notes": ""}, {"rank": 4, "title": "The Battle of the Five Armies", "year": "2014", "type": "movie", "notes": ""}, {"rank": 5, "title": "The Fellowship of the Ring", "year": "2001", "type": "movie", "notes": ""}, {"rank": 6, "title": "The Two Towers", "year": "2002", "type": "movie", "notes": ""}, {"rank": 7, "title": "The Return of the King", "year": "2003", "type": "movie", "notes": ""}]}, {"heading": "Story order: The Rings of Power TV continuity", "note": "\n\nThe series is set in Middle-earth’s Second Age, thousands of years before the Third Age stories in the films. It is a separate screen adaptation continuity; watch its released seasons in order.\n\nSeason 3 is announced for 11 November 2026; it has not premiered as of this guide’s 18 October 2026 update.", "items": [{"rank": 1, "title": "The Rings of Power — Season 1", "year": "2022", "type": "tv", "notes": ""}, {"rank": 2, "title": "The Rings of Power — Season 2", "year": "2024", "type": "tv", "notes": ""}]}]}, {"slug": "fast-and-furious", "title": "Fast & Furious Watch Order", "franchise": "Fast & Furious", "collection": "screen", "summary": "See where Tokyo Drift fits in the family saga.", "intro": "Fast & Furious begins with street racing and grows into a globe-spanning action saga. The titles can be confusing, but the main timeline has one especially important adjustment: Tokyo Drift is the third film released, not the third chapter in the central story.", "notes": "## Why move Tokyo Drift?\n\nThe later films place important character history before the Tokyo adventure. Moving it after Fast & Furious 6 lets those relationships develop before you reach that chapter. Flashbacks in later entries still revisit older events; they do not require you to rearrange entire films.\n\nFor extra connective material, The Turbo Charged Prelude for 2 Fast 2 Furious (2003) belongs between the first two movies. Los Bandoleros (2009) belongs before Fast & Furious. Both are optional shorts. The animated Spy Racers series is a spin-off rather than essential homework for the main films.\n\n## Peppermoon’s recommendation\n\nChoose story order for a first marathon if you want the character journey to flow more naturally. Choose release order if you want to experience the changing scale and reveals as cinema audiences did. Hobbs & Shaw can be skipped without breaking the central family storyline.\n\nSources: Peacock on release order and Tokyo Drift (https://www.peacocktv.com/blog/where-to-watch-the-fast-and-furious-movies-in-order); Fast & Furious chronology guide (https://www.itechguides.com/the-fast-furious-timeline-explained-where-tokyo-drift-fits/).", "image_url": "", "image_alt": "", "status": "published", "display_order": 5, "release_sections": [{"heading": "Release order", "note": "", "items": [{"rank": 1, "title": "The Fast and the Furious", "year": "2001", "type": "movie", "notes": ""}, {"rank": 2, "title": "2 Fast 2 Furious", "year": "2003", "type": "movie", "notes": ""}, {"rank": 3, "title": "The Fast and the Furious: Tokyo Drift", "year": "2006", "type": "movie", "notes": ""}, {"rank": 4, "title": "Fast & Furious", "year": "2009", "type": "movie", "notes": ""}, {"rank": 5, "title": "Fast Five", "year": "2011", "type": "movie", "notes": ""}, {"rank": 6, "title": "Fast & Furious 6", "year": "2013", "type": "movie", "notes": ""}, {"rank": 7, "title": "Furious 7", "year": "2015", "type": "movie", "notes": ""}, {"rank": 8, "title": "The Fate of the Furious", "year": "2017", "type": "movie", "notes": ""}, {"rank": 9, "title": "Fast & Furious Presents: Hobbs & Shaw", "year": "2019", "type": "movie", "notes": ""}, {"rank": 10, "title": "Fast & Furious: Spy Racers", "year": "2019–2021", "type": "tv", "notes": ""}, {"rank": 11, "title": "F9: The Fast Saga", "year": "2021", "type": "movie", "notes": ""}, {"rank": 12, "title": "Fast X", "year": "2023", "type": "movie", "notes": ""}]}], "story_sections": [{"heading": "Story order", "note": "", "items": [{"rank": 1, "title": "The Fast and the Furious", "year": "2001", "type": "movie", "notes": ""}, {"rank": 2, "title": "2 Fast 2 Furious", "year": "2003", "type": "movie", "notes": ""}, {"rank": 3, "title": "Fast & Furious", "year": "2009", "type": "movie", "notes": ""}, {"rank": 4, "title": "Fast Five", "year": "2011", "type": "movie", "notes": ""}, {"rank": 5, "title": "Fast & Furious 6", "year": "2013", "type": "movie", "notes": ""}, {"rank": 6, "title": "Tokyo Drift", "year": "2006", "type": "movie", "notes": ""}, {"rank": 7, "title": "Furious 7", "year": "2015", "type": "movie", "notes": "parts of its setup overlap Tokyo Drift"}, {"rank": 8, "title": "The Fate of the Furious", "year": "2017", "type": "movie", "notes": ""}, {"rank": 9, "title": "Hobbs & Shaw", "year": "2019", "type": "movie", "notes": "a side adventure best placed here for viewing"}, {"rank": 10, "title": "F9", "year": "2021", "type": "movie", "notes": ""}, {"rank": 11, "title": "Fast X", "year": "2023", "type": "movie", "notes": ""}]}, {"heading": "Story order: TV side series", "note": "\n\nSpy Racers is an animated franchise spin-off. Its exact placement alongside the films is not needed to follow the main movie timeline, so treat it as a side story.", "items": [{"rank": 1, "title": "Fast & Furious: Spy Racers", "year": "2019–2021", "type": "tv", "notes": "TV series; optional side story"}]}]}, {"slug": "marvel-cinematic-universe", "title": "Marvel Cinematic Universe Watch Order", "franchise": "Marvel Cinematic Universe", "collection": "screen", "summary": "Follow the MCU films through the Avengers and multiverse eras.", "intro": "The easiest first watch is release order: it follows how the MCU introduced its characters, reveals and post-credit connections. Story order follows the events inside the universe. Choose Movies only if you want to skip every series, or Movies + TV for the broader MCU viewing path.\n\nAbout the multiverse: What If...?, Marvel Zombies and The Fantastic Four: First Steps are MCU multiverse stories set on alternate branches or worlds. They are included in Movies + TV release order, but shown in a separate section in story order so they are not mistaken for events on the main MCU timeline.", "notes": "## Which shows are most useful alongside the films?\n\nFor viewers who want a shorter series list: watch WandaVision before Doctor Strange in the Multiverse of Madness; The Falcon and the Winter Soldier before Captain America: Brave New World; Ms. Marvel before The Marvels; and Loki for the TVA and multiverse background. The full Movies + TV option above includes the MCU series beyond these key connections.\n\n## Peppermoon’s recommendation\n\nUse release order for a first viewing. If you choose story order, some post-credit scenes still work best when watched in release order. Black Widow and Ant-Man and the Wasp contain credits scenes tied to later story events, so consider saving those scenes until after Avengers: Endgame and Avengers: Infinity War, respectively.\n\nThis guide lists feature films and television series; it leaves out short films and one-off specials. TV entries are listed by season where a season has a distinct place in the story. Release information checked 18 October 2026.\n\nSources: Marvel: Complete MCU timeline on Disney+ (https://www.marvel.com/articles/movies/mcu-timeline-order-disney-plus); Rotten Tomatoes MCU timeline guide (https://editorial.rottentomatoes.com/guide/marvel-movies-in-order/); GamesRadar MCU movies and TV timeline (https://www.gamesradar.com/mcu-timeline-marvel-movies-tv-shows/).", "image_url": "", "image_alt": "", "status": "published", "display_order": 6, "release_sections": [{"heading": "Release order", "note": "", "items": [{"rank": 1, "title": "Iron Man", "year": "2008", "type": "movie", "notes": ""}, {"rank": 2, "title": "The Incredible Hulk", "year": "2008", "type": "movie", "notes": ""}, {"rank": 3, "title": "Iron Man 2", "year": "2010", "type": "movie", "notes": ""}, {"rank": 4, "title": "Thor", "year": "2011", "type": "movie", "notes": ""}, {"rank": 5, "title": "Captain America: The First Avenger", "year": "2011", "type": "movie", "notes": ""}, {"rank": 6, "title": "The Avengers", "year": "2012", "type": "movie", "notes": ""}, {"rank": 7, "title": "Iron Man 3", "year": "2013", "type": "movie", "notes": ""}, {"rank": 8, "title": "Thor: The Dark World", "year": "2013", "type": "movie", "notes": ""}, {"rank": 9, "title": "Captain America: The Winter Soldier", "year": "2014", "type": "movie", "notes": ""}, {"rank"